class Vector2D
{
    vector< vector< int >>a;
    int r = 0, c = 0;
    void skip()
    {
        while (r < (int) a.size() && c == (int) a[r].size())
        {
            ++r;
            c = 0;
        }
    }
public:
    Vector2D(vector< vector< int >>& vec) : a(vec)
    {
    }
    int next()
    {
        skip();
        return a[r][c++];
    }
    bool hasNext()
    {
        skip();
        return r < (int) a.size();
    }
};
